body[data-atom-app=quick-notes] .note-entry>.actions{gap:9px;align-items:center;justify-content:end}
body[data-atom-app=quick-notes] .note-entry>.actions button{padding:0;min-height:25px;flex:none;font-size:10px;background:transparent!important}
body[data-atom-app=quick-notes] .screen>.row>.actions button{background:transparent!important;font-size:12px;padding:4px 8px}
body[data-atom-app=quick-notes] .screen>.row>.actions button[data-action=new]{background:var(--atom-accent,#007aff)!important;color:white!important;border-radius:16px!important;padding:5px 13px}
body[data-atom-app=quick-notes] [data-action=save]{background:var(--atom-accent,#007aff)!important;color:#fff!important}
body[data-atom-app=today] header>button{background:var(--atom-accent,#007aff)!important;color:white!important;border-radius:18px!important}
